-- stg_mc_inventory_snapshot: part 1 of 1, 62 rows. NOT APPLIED, branch only.
-- Licence on every row comes from the FILE, never the filename.
create table if not exists public.stg_mc_inventory_snapshot (
  package text,
  harvest text,
  col text,
  col_2 text,
  source_packages text,
  item text,
  category text,
  location text,
  location_type text,
  sublocation text,
  patient text,
  quantity text,
  uom text,
  manifest text,
  p_b text,
  prod_batch_no text,
  lab_testing text,
  a_h text,
  exp_date text,
  s_b_date text,
  u_b_date text,
  date text,
  source_file text not null,
  file_sha256 text not null,
  licence text not null,
  file_window text,
  ingested_at timestamptz not null default now()
);
alter table public.stg_mc_inventory_snapshot enable row level security;
drop policy if exists stg_mc_inventory_snapshot_read on public.stg_mc_inventory_snapshot;
create policy stg_mc_inventory_snapshot_read on public.stg_mc_inventory_snapshot for select to authenticated using (true);
